import { useAnimatedStyle, useSharedValue } from 'react-native-reanimated'
import { withRepeat, withSequence, withTiming } from 'react-native-reanimated'

export const useShake = (distance = 8, duration = 60) => {
	const x = useSharedValue(0)

	const shake = () => {
		x.set(
			withSequence(
				withTiming(-distance, { duration }),
				withRepeat(
					withSequence(
						withTiming(distance, { duration }),
						withTiming(-distance, { duration })
					),
					2, // shake 2 times
					false
				),
				withTiming(0, { duration })
			)
		)
	}

	const errorShakeStyle = useAnimatedStyle(() => ({
		transform: [{ translateX: x.get() }]
	}))

	return { errorShakeStyle, shake }
}
